# TypeScript Component Architecture

TypeScript patterns for building interactive components in the Oh My Brand! WordPress FSE theme. Covers class design, event handling, and DOM interaction for block frontends.

---

## When to Use

- Writing TypeScript components for block frontends
- Creating interactive UI elements (tabs, accordions, modals)
- Building editor components in `edit.tsx`
- Working with DOM manipulation in static blocks

---

## Reference Files

| File | Purpose |
|------|---------|
| [TabbedContent-example.ts](references/TabbedContent-example.ts) | Full component example (~90 lines) |
| [utility-functions.ts](references/utility-functions.ts) | Debounce/throttle utilities (~60 lines) |

---

## File Structure

```typescript
/**
 * Module description.
 */

// Imports – external first, then internal
import { someFunction } from 'external-library';
import { helperFunction } from '../utils/helper';

// Types and interfaces
interface ComponentConfig {
    readonly element: HTMLElement;
    options?: Record<string, unknown>;
}

// Constants
const DEFAULT_OPTION = 'value';

// Main implementation
export class ComponentName { }

// Module initialization
export function initComponent(): void { }
```

---

## Strict Mode

TypeScript `strict: true` is enforced. All client-side code must be TypeScript (no `.js` files in `src/`).

---

## Type Definitions

### Interfaces vs Types

```typescript
// Interface for component configuration
interface TabConfig {
    readonly selector: string;
    defaultTab?: string;
}

// Type for function signatures
type ClickHandler = (event: MouseEvent) => void;
```

### Readonly Properties

```typescript
interface BlockConfig {
    readonly id: string;
    options: Record<string, unknown>; // Can be modified
}

class Component {
    private readonly _element: HTMLElement;
    private readonly _config: Required<TabConfig>;
}
```

---

## Naming Conventions

| Type | Convention | Example |
|------|------------|---------|
| Classes | PascalCase | `TabbedContent` |
| Interfaces | PascalCase | `TabConfig` |
| Functions | camelCase | `initComponent()` |
| Variables | camelCase | `currentIndex` |
| Constants | SCREAMING_SNAKE | `DEFAULT_ACTIVE_TAB` |
| Private fields | underscore prefix | `_currentTab` |
| Files | kebab-case | `tabbed-content.ts` |

> **Note:** This project uses underscore-prefixed private fields (`_currentTab`) instead of the `#` prefix for better compatibility with older browsers and simpler transpilation. Arrow function methods are not required; standard method syntax is preferred.

---

## Classes

```typescript
export class TabbedContent {
    private readonly _element: HTMLElement;
    private readonly _config: Required<TabConfig>;
    private _currentTab: string;

    constructor(element: HTMLElement, config: TabConfig = {}) {
        this._element = element;
        this._config = this._mergeConfig(config);
        this._currentTab = this._config.defaultTab;
        this._bindEvents();
        this._render();
    }

    public switchTab(tabId: string): void {
        this._currentTab = tabId;
        this._updateUI();
    }

    public destroy(): void {
        this._removeEvents();
    }

    private _mergeConfig(config: TabConfig): Required<TabConfig> {
        return {
            selector: config.selector,
            defaultTab: config.defaultTab ?? 'tab1',
        };
    }

    private _bindEvents(): void {
        const buttons = this._element.querySelectorAll<HTMLButtonElement>('[data-tab]');
        buttons.forEach(button => {
            button.addEventListener('click', this._handleClick);
        });
    }

    private _removeEvents(): void {
        const buttons = this._element.querySelectorAll<HTMLButtonElement>('[data-tab]');
        buttons.forEach(button => {
            button.removeEventListener('click', this._handleClick);
        });
    }

    private _handleClick(event: MouseEvent): void {
        const button = event.currentTarget as HTMLButtonElement;
        const tabId = button.getAttribute('data-tab');
        if (tabId) {
            this.switchTab(tabId);
        }
    }

    private _render(): void {
        // Initial rendering logic
    }

    private _updateUI(): void {
        // Update active tab and panel
    }
}
```

See [TabbedContent-example.ts](references/TabbedContent-example.ts) for a full implementation.

---

## Functions

```typescript
export function debounce<T extends (...args: unknown[]) => unknown>(
    func: T,
    wait: number
): (...args: Parameters<T>) => void {
    let timeoutId: ReturnType<typeof setTimeout> | null = null;

    return function (this: unknown, ...args: Parameters<T>): void {
        if (timeoutId !== null) clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            func.apply(this, args);
            timeoutId = null;
        }, wait);
    };
}
```

---

## DOM Manipulation

### Type-Safe Queries (with `as` cast)

```typescript
function $<T extends HTMLElement>(selector: string, parent: ParentNode = document): T | null {
    return parent.querySelector(selector) as T | null;
}

// Usage
const tabs = $<HTMLDivElement>('.tabs');
if (tabs) {
    const buttons = tabs.querySelectorAll<HTMLButtonElement>('[data-tab]');
}
```

### Null Handling

```typescript
// Early return with guard
const element = document.querySelector<HTMLElement>('.tabs');
if (!element) return;

// Optional chaining
const currentTab = element?.getAttribute('data-current') ?? 'tab1';

// Assertion only when guaranteed
const nav = document.querySelector<HTMLElement>('.tabs-nav')!;
```

---

## Event Handling

### Regular Method Syntax

```typescript
class Component {
    private _handleClick(event: MouseEvent): void {
        const target = event.currentTarget as HTMLElement;
        this._doSomething(target);
    }
}
```

Arrow function methods are not required; standard method syntax is preferred to maintain consistent `this` context when used as callbacks.

### Custom Events

```typescript
this._element.dispatchEvent(
    new CustomEvent('tabs:change', {
        bubbles: true,
        detail: { tabId: this._currentTab },
    })
);
```

---

## Exports

### Named Exports Only

```typescript
// ✅ Good – named exports
export class TabbedContent { }
export function initTabs(): void { }
export type { TabConfig, ClickHandler };

// ❌ Bad – default exports
export default class TabbedContent { }
```

---

